-- Correct Cambridge 9 Test 2; retain question IDs and attempt history.
-- Source: https://engnovate.com/ielts-reading-tests/cambridge-ielts-09-academic-reading-test-2/
begin;
do $repair$
declare
  exam_id uuid;
  section_id_value uuid;
  group_id_value uuid;
  group_data jsonb;
  question_data jsonb;
  affected integer;
begin
  select id into exam_id from public.skill_tests where slug = 'cam-9-2';
  if exam_id is null then raise exception 'Missing Cambridge 9 Test 2'; end if;
  if (select count(*) from public.skill_questions q join public.skill_question_groups g on g.id = q.group_id join public.skill_sections s on s.id = g.section_id where s.test_id = exam_id) <> 40 then
    raise exception 'Expected 40 Cambridge 9 Test 2 questions';
  end if;
  -- Free final positions before moving existing questions between groups.
  update public.skill_questions q set order_index = q.source_number + 100
  from public.skill_question_groups g, public.skill_sections s
  where q.group_id = g.id and g.section_id = s.id and s.test_id = exam_id;
  for group_data in select value from jsonb_array_elements($data$[{"section":1,"order":1,"instruction":"<h3>Questions 1–6</h3><p>Reading Passage 1 has nine sections, A–I.</p><p>Which section contains the following information?</p>","display":"matching-info","config":{"sectionLabels":["A","B","C","D","E","F","G","H","I"]},"questions":[{"number":1,"order":1,"type":"matching","display":"matching-info","html":"","prompt":"an account of a national policy initiative","options":[],"answer":"H","accepted":[],"explanation":"Đoạn H mô tả New Zealand Disability Strategy, chính sách quốc gia nhằm cải thiện cơ hội học tập cho người khuyết tật."},{"number":2,"order":2,"type":"matching","display":"matching-info","html":"","prompt":"a description of a global team effort","options":[]},{"number":3,"order":3,"type":"matching","display":"matching-info","html":"","prompt":"a hypothesis as to one reason behind the growth in classroom noise","options":[]},{"number":4,"order":4,"type":"matching","display":"matching-info","html":"","prompt":"a demand for suitable worldwide regulations","options":[]},{"number":5,"order":5,"type":"matching","display":"matching-info","html":"","prompt":"a list of medical conditions which place some children more at risk from noise than others","options":[]},{"number":6,"order":6,"type":"matching","display":"matching-info","html":"","prompt":"the estimated proportion of children in New Zealand with auditory problems","options":[]}]},{"section":1,"order":2,"instruction":"<h3>Questions 7–10</h3><p>Answer the questions below.</p><p>Choose <strong>NO MORE THAN TWO WORDS AND/OR A NUMBER</strong> from the passage for each answer.</p>","display":"fill-blank","config":{},"questions":[{"number":7,"order":1,"type":"fill","display":"fill-blank","html":"","prompt":"For what period of time has hearing loss in schoolchildren been studied in New Zealand?","options":[]},{"number":8,"order":2,"type":"fill","display":"fill-blank","html":"","prompt":"In addition to machinery noise, what other type of noise can upset children with autism?","options":[]},{"number":9,"order":3,"type":"fill","display":"fill-blank","html":"","prompt":"What term is used to describe the hearing problems of schoolchildren which have not been diagnosed?","options":[]},{"number":10,"order":4,"type":"fill","display":"fill-blank","html":"","prompt":"What part of the New Zealand Disability Strategy aims to give schoolchildren equal opportunity?","options":[]}]},{"section":1,"order":3,"instruction":"<h3>Questions 11–12</h3><p>Choose <strong>TWO</strong> letters, A–F.</p><p>The list below includes factors contributing to classroom noise.</p>","display":"multiple-choice-2","config":{"answerSlots":2},"questions":[{"number":11,"order":1,"type":"mcq","display":"multiple-choice-2","html":"","prompt":"Which TWO are mentioned by the writer?","options":["current teaching methods","echoing corridors","cooling systems","large class sizes","loud-voiced teachers","playground games"],"answer":"A","accepted":["C"],"explanation":""},{"number":12,"order":2,"type":"mcq","display":"multiple-choice-2","html":"","prompt":"Which TWO are mentioned by the writer?","options":["current teaching methods","echoing corridors","cooling systems","large class sizes","loud-voiced teachers","playground games"],"answer":"C","accepted":["A"],"explanation":""}]},{"section":1,"order":4,"instruction":"<h3>Questions 13</h3><p>Choose the correct letter, A, B, C or D.</p>","display":"multiple-choice","config":{},"questions":[{"number":13,"order":1,"type":"mcq","display":"multiple-choice","html":"","prompt":"What is the writer's overall purpose in writing this article?","options":["to compare different methods of dealing with auditory problems","to provide solutions for overly noisy learning environments","to increase awareness of the situation of children with auditory problems","to promote New Zealand as a model for other countries to follow"]}]},{"section":2,"order":1,"instruction":"<h3>Questions 14–17</h3><p>Reading Passage 2 has seven paragraphs, A–G.</p><p>Which paragraph contains the following information?</p>","display":"matching-info","config":{"sectionLabels":["A","B","C","D","E","F","G"]},"questions":[{"number":14,"order":1,"type":"matching","display":"matching-info","html":"","prompt":"examples of different ways in which the parallax principle has been applied","options":[]},{"number":15,"order":2,"type":"matching","display":"matching-info","html":"","prompt":"a description of an event which prevented a transit observation","options":[]},{"number":16,"order":3,"type":"matching","display":"matching-info","html":"","prompt":"a statement about potential future discoveries leading on from transit observations","options":[]},{"number":17,"order":4,"type":"matching","display":"matching-info","html":"","prompt":"a description of physical states connected with Venus which early astronomical instruments failed to overcome","options":[]}]},{"section":2,"order":2,"instruction":"<h3>Questions 18–21</h3><p>Look at the following statements and the list of people below.</p><p>Match each statement with the correct person, A, B, C or D.</p>","display":"matching-feature","config":{"featureOptions":["Edmond Halley","Johannes Kepler","Guillaume Le Gentil","Johann Franz Encke"]},"questions":[{"number":18,"order":1,"type":"matching","display":"matching-feature","html":"","prompt":"He calculated the distance of the Sun from the Earth based on observations of Venus with a fair degree of accuracy.","options":[]},{"number":19,"order":2,"type":"matching","display":"matching-feature","html":"","prompt":"He understood that the distance of the Sun from the Earth could be worked out by comparing observations of a transit.","options":[]},{"number":20,"order":3,"type":"matching","display":"matching-feature","html":"","prompt":"He realised that the time taken by a planet to go round the Sun depends on its distance from the Sun.","options":[]},{"number":21,"order":4,"type":"matching","display":"matching-feature","html":"","prompt":"He witnessed a Venus transit but was unable to make any calculations.","options":[]}]},{"section":2,"order":3,"instruction":"<h3>Questions 22–26</h3><p>Do the following statements agree with the information given in Reading Passage 2?</p><p>Write</p><p><strong>TRUE</strong> if the statement agrees with the information</p><p><strong>FALSE</strong> if the statement contradicts the information</p><p><strong>NOT GIVEN</strong> if there is no information on this</p>","display":"tfng","config":{},"questions":[{"number":22,"order":1,"type":"tfng","display":"tfng","html":"","prompt":"Halley observed one transit of the planet Venus.","options":[]},{"number":23,"order":2,"type":"tfng","display":"tfng","html":"","prompt":"Le Gentil managed to observe a second Venus transit.","options":[]},{"number":24,"order":3,"type":"tfng","display":"tfng","html":"","prompt":"The shape of Venus appears distorted when it starts to pass in front of the Sun.","options":[]},{"number":25,"order":4,"type":"tfng","display":"tfng","html":"","prompt":"Early astronomers suspected that the atmosphere on Venus was toxic.","options":[]},{"number":26,"order":5,"type":"tfng","display":"tfng","html":"","prompt":"The parallax principle allows astronomers to work out how far away distant stars are from the Earth.","options":[]}]},{"section":3,"order":1,"instruction":"<h3>Questions 27–31</h3><p>Choose the correct letter, A, B, C or D.</p>","display":"multiple-choice","config":{},"questions":[{"number":27,"order":1,"type":"mcq","display":"multiple-choice","html":"","prompt":"Neuroeconomics is a field of study which seeks to","options":["cause a change in how scientists understand brain chemistry.","understand how good decisions are made in the brain.","understand how the brain is linked to achievement in competitive fields.","trace the specific firing patterns of neurons in different areas of the brain."]},{"number":28,"order":2,"type":"mcq","display":"multiple-choice","html":"","prompt":"According to the writer, iconoclasts are distinctive because","options":["they create unusual brain circuits.","their brains function differently.","their personalities are distinctive.","they make decisions easily."]},{"number":29,"order":3,"type":"mcq","display":"multiple-choice","html":"","prompt":"According to the writer, the brain works efficiently because","options":["it uses the eyes quickly.","it interprets data logically.","it generates its own energy.","it relies on previous events."]},{"number":30,"order":4,"type":"mcq","display":"multiple-choice","html":"","prompt":"The writer says that perception is","options":["a combination of photons and sound waves.","a reliable product of what your senses transmit.","a result of brain processes.","a process we are usually conscious of."]},{"number":31,"order":5,"type":"mcq","display":"multiple-choice","html":"","prompt":"According to the writer, an iconoclastic thinker","options":["centralises perceptual thinking in one part of the brain.","avoids cognitive traps.","has a brain that is hardwired for learning.","has more opportunities than the average person."]}]},{"section":3,"order":2,"instruction":"<h3>Questions 32–37</h3><p>Do the following statements agree with the claims of the writer in Reading Passage 3?</p><p><strong>YES</strong> if the statement agrees with the claims of the writer</p><p><strong>NO</strong> if the statement contradicts the claims of the writer</p><p><strong>NOT GIVEN</strong> if it is impossible to say what the writer thinks about this</p>","display":"ynng","config":{},"questions":[{"number":32,"order":1,"type":"ynng","display":"ynng","html":"","prompt":"Exposure to different events forces the brain to think differently.","options":[]},{"number":33,"order":2,"type":"ynng","display":"ynng","html":"","prompt":"Iconoclasts are unusually receptive to new experiences.","options":[]},{"number":34,"order":3,"type":"ynng","display":"ynng","html":"","prompt":"Most people are too shy to try different things.","options":[]},{"number":35,"order":4,"type":"ynng","display":"ynng","html":"","prompt":"If you think in an iconoclastic way, you can easily overcome fear.","options":[]},{"number":36,"order":5,"type":"ynng","display":"ynng","html":"","prompt":"When concern about embarrassment matters less, other fears become irrelevant.","options":[]},{"number":37,"order":6,"type":"ynng","display":"ynng","html":"","prompt":"Fear of public speaking is a psychological illness.","options":[]}]},{"section":3,"order":3,"instruction":"<h3>Questions 38–40</h3><p>Complete each sentence with the correct ending, A–E, below.</p>","display":"sentence-ending","config":{"sentenceEndings":["requires both perceptual and social intelligence skills.","focuses on how groups decide on an action.","works in many fields, both artistic and scientific.","leaves one open to criticism and rejection.","involves understanding how organisations manage people."]},"questions":[{"number":38,"order":1,"type":"matching","display":"sentence-ending","html":"","prompt":"Thinking like a successful iconoclast is demanding because it","options":[]},{"number":39,"order":2,"type":"matching","display":"sentence-ending","html":"","prompt":"The concept of the social brain is useful to iconoclasts because it","options":[]},{"number":40,"order":3,"type":"matching","display":"sentence-ending","html":"","prompt":"Iconoclasts are generally an asset because their way of thinking","options":[]}]}]$data$::jsonb)
  loop
    select id into strict section_id_value from public.skill_sections where test_id = exam_id and section_no = (group_data->>'section')::integer;
    insert into public.skill_question_groups (section_id, order_index, instruction_html, display_type, config)
    values (section_id_value, (group_data->>'order')::integer, group_data->>'instruction', group_data->>'display', group_data->'config')
    on conflict (section_id, order_index) do update set instruction_html = excluded.instruction_html, display_type = excluded.display_type, config = excluded.config
    returning id into group_id_value;
    for question_data in select value from jsonb_array_elements(group_data->'questions')
    loop
      update public.skill_questions q set
        group_id = group_id_value, order_index = (question_data->>'order')::integer,
        question_type = question_data->>'type', display_type = question_data->>'display',
        question_html = question_data->>'html',
        explanation = coalesce(question_data->>'explanation', q.explanation),
        prompt = coalesce(question_data->>'prompt', q.prompt),
        options = coalesce(question_data->'options', q.options),
        answer_key = coalesce(question_data->>'answer', q.answer_key),
        accepted_answers = case when question_data ? 'accepted' then array(select jsonb_array_elements_text(question_data->'accepted')) else q.accepted_answers end
      from public.skill_question_groups old_group
      where old_group.id = q.group_id and old_group.section_id = section_id_value and q.source_number = (question_data->>'number')::integer;
      get diagnostics affected = row_count;
      if affected <> 1 then raise exception 'Expected one question for %', question_data->>'number'; end if;
    end loop;
  end loop;
end $repair$;
update public.skill_sections set content_html = $passage$<h2 class="text-3xl font-black text-[#007e64] mb-8">Hearing impairment in children</h2>
<p><strong>A</strong> Hearing impairment or other auditory function deficit in young children can have a major impact on their development of speech and communication, resulting in a detrimental effect on their ability to learn at school. This is likely to have major consequences for the individual and the population as a whole. The New Zealand Ministry of Health has found from research carried out over two decades that 6-10% of children in that country are affected by hearing loss.</p>
<p><strong>B</strong> A preliminary study in New Zealand has shown that classroom noise presents a major concern for teachers and pupils. Modern teaching practices, the organisation of desks</p>
<p>in the classroom, poor classroom acoustics, and mechanical means of ventilation such as air-conditioning units all contribute to the number of children unable to comprehend the teacher's voice. Education researchers Nelson and Soli have also suggested that recent trends in learning often involve collaborative interaction of multiple minds and tools as much as individual possession of information. This all amounts to heightened activity and noise levels, which have the potential to be particularly serious for children experiencing auditory function deficit. Noise in classrooms can only exacerbate their difficulty in comprehending and processing verbal communication with other children and instructions from the teacher.</p>
<p><strong>C</strong> Children with auditory function deficit are potentially failing to learn to their maximum potential because of noise levels generated in classrooms. The effects of noise on the ability of children to learn effectively in typical classroom environments are now the subject of increasing concern. The International Institute of Noise Control Engineering</p>
<p>(IEINCE), on the advice of the World Health Organization, has established an international working party, which includes New Zealand, to evaluate noise and reverberation control for school rooms.</p>
<p><strong>D</strong> While the detrimental effects of noise in classroom situations are not limited to children experiencing disability, those with a disability that affects their processing of speech and verbal communication could be extremely vulnerable. The auditory function deficits in question include hearing impairment, autistic spectrum disorders (ASD) and attention deficit disorders (ADD/ADHD).</p>
<p><strong>E</strong> Autism is considered a neurological and genetic life-long disorder that causes discrepancies in the way information is processed. This disorder is characterised by interlinking problems with social imagination, social communication and social interaction. According to Janzen, this affects the ability to understand and relate in typical ways to people, understand events and objects in the environment, and understand or respond to sensory stimuli. Autism does not allow learning or thinking in the same ways as in children who are developing normally.</p>
<p>Autistic spectrum disorders often result in major difficulties in comprehending verbal information and speech processing. Those experiencing these disorders often find sounds such as crowd noise and the noise generated by machinery painful and distressing. This is difficult to scientifically quantify as such extra-sensory stimuli vary greatly from one autistic individual to another. But a child who finds any type of noise in their classroom or learning space intrusive is likely to be adversely affected in their ability to process information.</p>
<p><strong>F</strong> The attention deficit disorders are indicative of neurological and genetic disorders and are characterised by difficulties with sustaining attention, effort and persistence, organisation skills and disinhibition. Children experiencing these disorders find it difficult to screen out unimportant information, and focus on everything in the environment rather than attending to a single activity. Background noise in the classroom becomes a major distraction, which can affect their ability to concentrate.</p>
<p><strong>G</strong> Children experiencing an auditory function deficit can often find speech and communication very difficult to isolate and process when set against high levels of background noise.</p>
<p>These levels come from outside activities that penetrate the classroom structure, from teaching activities, and other noise generated inside, which can be exacerbated by room reverberation. Strategies are needed to obtain the optimum classroom construction and perhaps a change in classroom culture and methods of teaching. In particular, the effects</p>
<p>of noisy classrooms and activities on those experiencing disabilities in the form of auditory function deficit need thorough investigation. It is probable that many undiagnosed children exist in the education system with ‘invisible’ disabilities. Their needs are less likely to be met than those of children with known disabilities.</p>
<p><strong>H</strong> The New Zealand Government has developed a New Zealand Disability Strategy and has embarked on a wide-ranging consultation process. The strategy recognises that people experiencing disability face significant barriers in achieving a full quality of life in areas such as attitude, education, employment and access to services. Objective 3 of the New Zealand Disability Strategy is to ‘Provide the Best Education for Disabled People’ by improving education so that all children, youth learners and adult learners will have equal opportunities to learn and develop within their already existing local school. For a successful education, the learning environment is vitally significant, so any effort to improve this is likely to be of great benefit to all children, but especially to those with auditory function disabilities.</p>
<p><strong>I</strong> A number of countries are already in the process of formulating their own standards for</p>
<p>the control and reduction of classroom noise. New Zealand will probably follow their example. The literature to date on noise in school rooms appears to focus on the effects on schoolchildren in general, their teachers and the hearing impaired. Only limited attention appears to have been given to those students experiencing the other disabilities involving auditory function deficit. It is imperative that the needs of these children are taken into account in the setting of appropriate international standards to be promulgated in future.</p>$passage$ where test_id = (select id from public.skill_tests where slug = 'cam-9-2') and section_no = 1;
update public.skill_sections set content_html = $passage$<h2 class="text-3xl font-black text-[#007e64] mb-8">Venus in Transit</h2>
<p>June 2004 saw the first passage, known as a ‘transit’, of the planet Venus across the face of the Sun in</p>
<p>122 years. Transits have helped shape our view of the whole Universe, as Heather Cooper and Nigel Henbest explain</p>
<p><strong>A</strong> On 8 June 2004, more than half the population of the world were treated to a rare astronomical event. For over six hours, the planet Venus steadily inched its way over the surface of the Sun. This ‘transit’ of Venus was the first since 6 December 1882. On that occasion, the American astronomer Professor Simon Newcomb led a party to South Africa to observe the event. They were based at a girls’ school, where — it is alleged — the combined forces of three schoolmistresses outperformed the professionals with the accuracy of their observations.</p>
<p><strong>B</strong> For centuries, transits of Venus have drawn explorers and astronomers alike to the four corners of the globe. And you can put it all down to the extraordinary polymath Edmond Halley. In November 1677, Halley observed a transit of the innermost planet, Mercury, from the desolate island of St Helena in the South Pacific. He realised that, from different latitudes, the passage of the planet across the Sun’s disc would appear to differ. By timing the transit from two widely-separated locations, teams of astronomers could calculate the parallax angle - the apparent difference in position of an astronomical body due to a difference in the observer's position. Calculating this angle would allow astronomers to measure what was then the ultimate goal: the distance of the Earth from the Sun. This distance is known as the ‘astronomical unit’ or AU.</p>
<p><strong>C</strong> Halley was aware that the AU was one of the most fundamental of all astronomical measurements. Johannes Kepler, in the early 17" century, had shown that the distances of the planets from the Sun governed their orbital speeds, which were easily measurable. But no-one had found a way to calculate accurate distances to the planets from the Earth. The goal was to measure the AU; then, knowing the orbital speeds of all the other planets round the Sun, the scale of the Solar System would fall into place. However, Halley realised that Mercury was so far away that its parallax angle would be very difficult to determine. As Venus was closer to the Earth, its parallax angle would be larger, and Halley worked out that by using Venus it would be possible to measure the</p>
<p>Sun’s distance to 1 part in 500. But there was a problem: transits of Venus, unlike those of Mercury, are rare, occurring in pairs roughly eight years apart every hundred or so years. Nevertheless, he accurately predicted that Venus would cross the face of the Sun in both 1761 and 1769 - though he didn't survive to see either.</p>
<p><strong>D</strong> Inspired by Halley’s suggestion of a way to pin down the scale of the Solar System, teams of British and French astronomers set out on expeditions to places as diverse as India and Siberia. But things weren't helped by Britain and France being at war. The person who deserves most sympathy is the French astronomer Guillaume Le Gentil. He was thwarted by the fact that the British were besieging his observation site at Pondicherry in India. Fleeing on a French warship crossing the Indian Ocean, Le Gentil saw a wonderful transit — but the ship’s pitching and rolling ruled out any attempt at making accurate observations. Undaunted, he remained south of the equator, keeping himself busy by studying the islands of Mauritius and Madagascar before setting off to observe the next transit in the Philippines. Ironically after travelling nearly 50,000 kilometres, his view was clouded out at the last moment, a very dispiriting experience.</p>
<p><strong>E</strong> While the early transit timings were as precise as instruments would allow, the measurements were dogged by the ‘black drop’ effect. When Venus begins to cross the Sun’s disc, it looks smeared not circular - which makes it difficult to establish timings. This is due to diffraction of light. The second problem is that Venus exhibits a halo of light when it is seen just outside the Sun’s disc. While this showed astronomers that Venus was surrounded by a thick layer of gases refracting sunlight around it, both effects made it impossible to obtain accurate timings.</p>
<p><strong>F</strong> But astronomers laboured hard to analyse the results of these expeditions to observe Venus transits. Johann Franz Encke, Director of the Berlin Observatory, finally determined a value for the AU based on all these parallax measurements:</p>
<p>153,340,000 km. Reasonably accurate for the time, that is quite close to today’s value of 149,597,870 km, determined by radar, which has now superseded transits and all other methods in accuracy. The AU is a cosmic measuring rod, and the basis of how we scale the Universe today. The parallax principle can be extended to measure the distances to the stars. If we look at a star in January - when Earth is at one point in its orbit — it will seem to be in a different position from where it appears six months later. Knowing the width of Earth’s orbit, the parallax shift lets astronomers calculate the distance.</p>
<p><strong>G</strong> June 2004’s transit of Venus was thus more of an astronomical spectacle than a scientifically important event. But such transits have paved the way for what might prove to be one of the most vital breakthroughs in the cosmos - detecting Earth-sized planets orbiting other stars.</p>$passage$ where test_id = (select id from public.skill_tests where slug = 'cam-9-2') and section_no = 2;
commit;
